<?php session_start(); require '../config.php'; require_admin(); $search=trim($_GET['search']??''); $status=$_GET['status']??''; $sql="SELECT * FROM applications WHERE 1=1";$args=[];if($search!==''){$sql.=" AND (full_name LIKE ? OR application_no LIKE ? OR parent_phone LIKE ?)";$like="%$search%";$args=[$like,$like,$like];}if(in_array($status,['Pending','Under Review','Accepted','Rejected'],true)){$sql.=" AND status=?";$args[]=$status;}$sql.=" ORDER BY created_at DESC";$st=db()->prepare($sql);$st->execute($args);$apps=$st->fetchAll(); ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Applications</title><link rel="stylesheet" href="../assets/css/style.css"></head><body class="admin-body"><header class="admin-head"><div><img src="../assets/images/school-logo.png"><strong>ME’RAJ ADMIN PORTAL</strong></div><nav><a href="dashboard.php">Dashboard</a><a href="applications.php">Applications</a><a href="media.php">Media</a><a href="logout.php">Logout</a></nav></header><main class="admin-main"><div class="container"><div class="section-head"><h1>Admission Applications</h1></div><form class="filter" method="get"><input name="search" value="<?=e($search)?>" placeholder="Search name, application no. or phone"><select name="status"><option value="">All Statuses</option><?php foreach(['Pending','Under Review','Accepted','Rejected'] as $s): ?><option <?=$status===$s?'selected':''?>><?=$s?></option><?php endforeach; ?></select><button class="btn">Search</button></form><div class="card table-card"><div class="table-wrap"><table><thead><tr><th>Application No.</th><th>Student</th><th>Section/Class</th><th>Parent Phone</th><th>Status</th><th>Submitted</th><th></th></tr></thead><tbody><?php foreach($apps as $a): ?><tr><td><?=e($a['application_no'])?></td><td><?=e($a['full_name'])?></td><td><?=e($a['applying_section'])?> / <?=e($a['class_applied'])?></td><td><?=e($a['parent_phone'])?></td><td><span class="status status-<?=strtolower(str_replace(' ','-',$a['status']))?>"><?=e($a['status'])?></span></td><td><?=e($a['created_at'])?></td><td><a class="btn btn-small" href="application.php?no=<?=urlencode($a['application_no'])?>">View</a></td></tr><?php endforeach; ?></tbody></table></div></div></div></main></body></html>